    Args:
        obj: The object to wrap. Can be a class, callable, or any other object.

    Returns:
        A descriptor proxy that lazily initializes the wrapped object.
    """
    class DescriptorProxy:
        def __init__(self, wrapped):
            self._wrapped = wrapped
            self._initialized = False
            self._value = None

        def __get__(self, instance, owner=None):
            # If accessed through the class, return the proxy itself
            if instance is None:
                return self

            # If already initialized, return the cached value
            if self._initialized:
                return self._value

            wrapped = self._wrapped
            result = None

            try:
                # If it's a class, instantiate it
                if isinstance(wrapped, type):
                    try:
                        wrapped_instance = wrapped()

                        # If the instance has a __get__ method, use it
                        if hasattr(wrapped_instance, '__get__'):
                            result = wrapped_instance.__get__(instance, owner)
                        else:
                            # Otherwise, return the instance
                            result = wrapped_instance
                    except Exception:
                        # If instantiation fails, return the class itself
                        result = wrapped

                # If it's a descriptor, use its __get__ method
                elif hasattr(wrapped, '__get__'):
                    try:
                        result = wrapped.__get__(instance, owner)
                    except Exception:
                        # If __get__ fails, fall back to other methods
                        result = None

                # If it's a callable but not a class, call it
                elif callable(wrapped) and not isinstance(wrapped, type):
                    try:
                        result = wrapped()
                    except Exception:
                        # If calling fails, return the wrapped object
                        result = wrapped

                # If we haven't set a result yet, use the wrapped object
